"""Create a review board solely from actual recorded game screenshots."""
import argparse,asyncio,base64,json,hashlib
from pathlib import Path
from playwright.async_api import async_playwright
ROOT=Path(__file__).resolve().parents[1]
def data(p):return 'data:image/png;base64,'+base64.b64encode(p.read_bytes()).decode()
async def main(args):
 folder=ROOT/args.folder;r=json.loads((folder/'report.json').read_text(encoding='utf8'));assert r['passed'] and len(r['results'])==8 and r['mobileWin']['state']=='won';old=ROOT/'docs/escort-qa/design/desktop-street.png';names=['dawn-combat.png','rain-combat.png','night-canal.png','night-gate.png','opening-desktop.png','mobile-combat.png'];titles=['新版 · 晨街战斗','雨巷 · 湿石与冷光','夜岸 · 灯火与水面','归巷 · 终章院门','新版 · 开场与界面','手机 · 同屏操作'];cards='<article><h2>旧版实景 · 游戏区域裁切</h2><canvas id="before" width="1032" height="548"></canvas><p>几何人物、重复楼体与平面地面</p></article>'
 cards+=f'<article><h2>{titles[0]}</h2><img src="{data(folder/names[0])}"><p>绘画角色、动作姿态、纹理街区与实体灯车</p></article>'
 for title,name in zip(titles[1:],names[1:]):cards+=f'<article class="'+('phone' if name.startswith('mobile') else '')+f'"><h2>{title}</h2><img src="{data(folder/name)}">'+('<div class="review-notes"><b>角色与动作</b>六姿态守灯人、四类对手与绘画灯车。<b>场景与光影</b>晨街、雨巷、夜岸与终章；材质、天气和暖光统一。<b>实际操作与边界</b>键盘和多指输入，正常生命与有限资源。<br>有限姿态动画；质感是否合意，交回评审。</div>' if name.startswith('mobile') else '')+'</article>'
 html='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><style>*{box-sizing:border-box}body{margin:0;background:#0e1c25;color:#e9dcc1;font-family:'Microsoft YaHei',sans-serif;width:1440px;padding:42px}header{border-bottom:1px solid #a38b5544;margin-bottom:27px;padding-bottom:22px}small{font-size:11px;color:#d0af70;letter-spacing:3px}h1{font:46px 'KaiTi',serif;margin:12px 0}header p,footer{color:#a8bbb0;font-size:13px;line-height:1.8}.grid{display:grid;grid-template-columns:1fr 1fr;gap:24px}article{background:#172b34;border:1px solid #947f4c44;border-radius:7px;overflow:hidden}h2{font:21px 'KaiTi',serif;margin:0;padding:17px 20px;color:#ead3a4}img,canvas{width:100%;height:auto;display:block}article p{font-size:12px;color:#a8bbb0;padding:0 20px}.phone{grid-column:1/-1;display:grid;grid-template-columns:1fr 1fr;padding-bottom:24px}.phone h2{grid-column:1/-1}.phone img{width:auto;height:535px;max-width:100%;margin:auto}.review-notes{align-self:center;padding:25px 45px;color:#b5c7bb;font-size:17px;line-height:2}.review-notes b{display:block;color:#e1c28d;font-size:21px;margin-top:19px}footer{margin-top:24px}</style><header><small>ALLEYLIGHT ESCORT · VISUAL REVIEW</small><h1>街巷护送 · 实景对比</h1><p>开场、战斗、晨街、雨巷、夜岸、终章与手机。以下均来自实际游戏运行；对比图只作排版与标注。<br>美术素材由AI辅助原创制作；技术验证不代表用户已认可质感，本轮交回视觉评审。</p></header><section class="grid">'''+cards+'</section><footer>保留8关玩法、正常生命与有限资源。规则引擎未改；旧33款与72项图鉴保留。<br>有限姿态动画与分层绘画场景；无商业角色、ROM或原游戏资源。</footer><script>const im=new Image();im.onload=()=>{document.querySelector("#before").getContext("2d").drawImage(im,40,493,1032,548,0,0,1032,548);window.oldReady=true};im.src='+json.dumps(data(old))+';</script></html>'
 async with async_playwright() as pw:
  b=await pw.chromium.launch();p=await b.new_page(viewport={'width':1440,'height':1000},device_scale_factor=1);await p.set_content(html);await p.wait_for_function('window.oldReady');await p.evaluate('Promise.all([...document.images].map(i=>i.decode()))');await p.screenshot(path=str(folder/'review-board.png'),full_page=True);await b.close()
 metadata={'passed':True,'source':'Actual recorded game screenshots, no generated mockup inserted','folder':args.folder,'board':'review-board.png','oldScreenshotCrop':[40,493,1032,548],'files':[{'file':p.relative_to(ROOT).as_posix(),'sha256':hashlib.sha256(p.read_bytes()).hexdigest()} for p in [old,*[folder/n for n in names]]],'boardSHA256':hashlib.sha256((folder/'review-board.png').read_bytes()).hexdigest()};(folder/'review-board.json').write_text(json.dumps(metadata,ensure_ascii=False,indent=2)+'\n',encoding='utf8');print(json.dumps({'passed':True,'board':str(folder/'review-board.png'),'bytes':(folder/'review-board.png').stat().st_size}))
if __name__=='__main__':
 a=argparse.ArgumentParser();a.add_argument('--folder',default='docs/escort-qa/visual-v3');asyncio.run(main(a.parse_args()))
